head.script:
scwin.trigger1_onclick = function(e) {
    grid1.setBottomRowIndex(6);
    grid1.setCellClass(4, 0, "vcheck");
};
scwin.trigger2_onclick = function(e) {
    grid1.removeCellClass(4, 0);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 및 개발자모드(F12)실행 후 'setCellClass'버튼을 클릭한다.
    //1. After executing sample and developer mode (F12), click 'setCellClass' button.
    //Verify step 1. The red line in the row_4 column flashes.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_0').hasClass('vcheck')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'removeCellClass'버튼을 클릭하고 inspect를 클릭하여 row_4를 클릭해서 확인한다. 
    //2. Click the 'removeCellClass' button, click inspect, and click on row_4 to confirm.
    //Verify step 2. There is no blinking of the red line in the row_4 column and the vcheck value is not visible in the class area.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_0').hasClass('vcheck')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.arr = [];
    for (var i = 0; i < 200; i++) {
        arr.push("row_" + i);
    }
    //		grid1.setData(arr);        
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
